{
  "name": "opencode-orchestrator-kit",
  "version": "1.3.0",
  "description": "OpenCode plugin that routes coding work across specialist agents. Registers the orchestrator workflow, plan-board tooling, session-memory rules, kit skills, and the /start-session, /recall, /research-mode, and /close-session commands.",
  "homepage": "https://nicogenti.github.io/opencode-orchestrator-kit/",
  "keywords": [
    "opencode",
    "opencode-plugin",
    "opencode-agents",
    "ai-agents",
    "multi-agent",
    "orchestrator",
    "coding-agent",
    "llm",
    "developer-tools"
  ],
  "license": "MIT",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/NicoGenti/opencode-orchestrator-kit.git",
    "directory": "plugin"
  },
  "type": "module",
  "exports": {
    ".": "./src/index.ts"
  },
  "files": [
    "src",
    "types",
    "assets",
    "README.md"
  ],
  "dependencies": {
    "@toon-format/toon": "4.4.0"
  },
  "peerDependencies": {
    "@opencode/plugin": "^2.1.0"
  },
  "scripts": {
    "prepack": "bun ../scripts/sync-assets.ts"
  }
}

import { Plugin } from "./runtime/opencode-plugin";
import type { AgentEditor } from "./runtime/opencode-plugin";

import { collectPackagedSkills } from "./assets";
import { loadPackagedCommands } from "./command";

import {
  collectAvailabilityWarnings,
  resolveTierMap,
  resolveTierValue,
} from "./tiers";
import type { ResolvedTierMap } from "./tiers";

import { collectPackagedAgents, parseModelRef } from "./agents";

import { registerPlanBoardTool } from "./plan-board-tool";

/** Prefix used for every kit signal printed to the console. */
const WARNING_PREFIX = "[opencode-orchestrator-kit]";

/**
 * opencode-orchestrator-kit plugin (Phase 3).
 *
 * Reads the plugin options `{ preset?, withExtras? }`, resolves the tier map
 * from the bundled presets ( throwing TierConfigError early on bad config ),
 * signals unavailable tier models against `ctx.model.list()` (non-fatal), and
 * registers: five commands (`/start-session`, `/quick`, `/recall`,
 * `/research-mode`, `/close-session`),
 * the 11 kit skills and the 16 packaged agents (+2 extras when `withExtras:
 * true`) via `ctx.agent.transform`.
 *
 * Phase 3 additionally registers the native `plan_board` tool (the pure
 * plan-board CLI port) via `ctx.tool.transform`; when the host does not
 * expose `ctx.tool` the registration degrades silently and setup stays
 * successful.
 *
 * Agent registration is an upsert guarded by `editor.get(id)`: user-configured
 * agents win. It never calls `editor.default(...)` — the user's startup agent
 * is NOT changed; orchestrator stays the default `mode: primary` kit agent;
 * `orchestrator-quick` is the opt-in alternate.
 *
 * Phase 5 registers each agent's V2 `permissions` (ordered rules, last match
 * wins): the frontmatter translation lives in permissions.ts, the kit invariants
 * (orchestrator cannot edit application code, only plan-writer can edit the
 * board root) are appended last and asserted before registration.
 *
 * Note: @opencode/plugin is a peer dependency not installed in this repo — the
 * import is served by the shipped 0.7.0 runtime stand-in (the peer dependency
 * `@opencode/plugin ^2.1.0` documents the real host contract; see the header of
 * src/runtime/opencode-plugin.ts and plugin/types/opencode-plugin-shim.d.ts).
 */
export default Plugin.define({
  id: "opencode-orchestrator-kit",
  async setup(ctx) {
    // 1. Options (all optional).
    const options = ctx.options ?? {};
    const presetName =
      typeof options.preset === "string" && options.preset.length > 0
        ? options.preset
        : undefined;
    const withExtras = options.withExtras === true;

    // 2. Tier resolution — throws TierConfigError BEFORE any registration
    //    (fail early, leave the runtime untouched on bad config).
    const tierMap = resolveTierMap(presetName);

    // 3. Unavailable models are signaled, never fatal.
    //    OpenCode 2.2 returns `{ location, data }` from ctx.model.list();
    //    2.1 returned a bare array. Accept both shapes.
    const listed = (await ctx.model.list()) as unknown;
    const registry: ReadonlyArray<{ providerID: string; id: string }> =
      Array.isArray(listed)
        ? (listed as Array<{ providerID: string; id: string }>)
        : ((listed as { data?: Array<{ providerID: string; id: string }> })
            ?.data ?? []);
    if (registry.length === 0) {
      console.warn(
        `${WARNING_PREFIX} runtime model registry is empty; skipping tier availability checks (preset: '${tierMap.preset}')`,
      );
    } else {
      for (const warning of collectAvailabilityWarnings(
        tierMap.models,
        tierMap.preset,
        registry,
      )) {
        console.warn(warning.message);
      }
    }

    // 4. Commands (/start-session, /recall, /research-mode, /close-session —
    //    packaged copies of the repo-root command/*.md documents).
    //    OpenCode 2.2 contract: `execute(input)` must return a promise AND
    //    deliver the prompt itself; the host chains `.then()` on the result.
    ctx.command.transform((editor) => {
      for (const packaged of loadPackagedCommands()) {
        editor.add({
          name: packaged.name,
          description: packaged.description,
          execute: async ({ sessionID, prompt, delivery }) => {
            if (typeof ctx.session.switchAgent === "function") {
              try {
                await ctx.session.switchAgent({
                  sessionID,
                  agent: packaged.agent,
                });
              } catch (error) {
                // The prompt is the essential part: a failed agent switch
                // must not block sending the command.
                console.warn(
                  `${WARNING_PREFIX} /${packaged.name}: could not switch the session to '${packaged.agent}' (${String(error)}); delivering the prompt on the current agent`,
                );
              }
            }
            await ctx.session.prompt({
              ...prompt,
              sessionID,
              text: packaged.body,
              delivery,
            });
          },
        });
      }
    });

    // 5. Skills.
    ctx.skill.transform((editor) => {
      for (const skill of collectPackagedSkills()) {
        editor.add({
          id: skill.id,
          name: skill.name,
          path: skill.path,
          content: skill.content,
        });
      }
    });

    // 6. Agents (upsert via ctx.agent.transform; user config wins).
    await ctx.agent.transform((editor) => {
      for (const agent of collectPackagedAgents(withExtras)) {
        registerAgent(editor, agent, tierMap);
      }
    });

    // 7. Native plan_board tool (Phase 3) via ctx.tool.transform; degrades
    //    silently when the host does not expose ctx.tool.
    registerPlanBoardTool(ctx);
  },
});

/**
 * Upsert one packaged agent into the editor unless the user already
 * configured an agent with the same id.
 */
function registerAgent(
  editor: AgentEditor,
  agent: ReturnType<typeof collectPackagedAgents>[number],
  tierMap: ResolvedTierMap,
): void {
  if (editor.get(agent.id)) {
    return; // user config wins
  }
  editor.update(agent.id, (info) => {
    const value = resolveTierValue(agent.model, tierMap.models, tierMap.preset);
    info.description = agent.description;
    // update() seeds "primary" for fresh ids — set mode explicitly every time
    // so subagents never leak into the primary-agent cycle.
    info.mode = agent.mode;
    info.model = parseModelRef(value);
    info.system = agent.system;

    // V2 ordered permission rules: frontmatter translation + kit invariants
    // (already composed and validated by collectPackagedAgents).
    info.permissions = agent.permissions;
  });
}
